        q=[(r,c)]; seen.add((r,c)); pts=[]
        while q:
          y,x=q.pop(); pts.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and g[yy][xx]==col and (yy,xx) not in seen:
              seen.add((yy,xx)); q.append((yy,xx))
        r0=min(y for y,x in pts); r1=max(y for y,x in pts); c0=min(x for y,x in pts); c1=max(x for y,x in pts)
        if all(g[r0][x]==col and g[r1][x]==col for x in range(c0,c1+1)) and all(g[y][c0]==col and g[y][c1]==col for y in range(r0,r1+1)):
          boxes.append((col,r0,r1,c0,c1))
    patterned=[]
    for col,a,b,c,d in boxes:
      pat=[[g[y][x]!=0 for x in range(c+1,d)] for y in range(a+1,b)]
      if any(any(row) for row in pat): patterned.append((col,a,b,c,d,pat))
